import requests
import time

def deny_access(url):
  while True:
    try:
      response = requests.get(url)
      response.raise_for_status()
      print(f"Access granted to {url}")
      break
    except requests.exceptions.HTTPError as e:
      print(f"Access denied to {url}: {e}")
      time.sleep(5)
